Here's a comprehensive X++ script to create a custom REST service in Dynamics AX (D365FO):

## 1. First, create the Data Contract Class

```x++
/// <summary>
/// Data contract class for customer information
/// </summary>
[DataContract]
public class CustomerServiceDataContract
{
    private CustAccount custAccount;
    private Name        customerName;
    private Phone       phone;
    private Email       email;
    private CustGroupId custGroup;

    [DataMember("CustomerAccount")]
    public CustAccount parmCustAccount(CustAccount _custAccount = custAccount)
    {
        custAccount = _custAccount;
        return custAccount;
    }

    [DataMember("CustomerName")]
    public Name parmCustomerName(Name _customerName = customerName)
    {
        customerName = _customerName;
        return customerName;
    }

    [DataMember("Phone")]
    public Phone parmPhone(Phone _phone = phone)
    {
        phone = _phone;
        return phone;
    }

    [DataMember("Email")]
    public Email parmEmail(Email _email = email)
    {
        email = _email;
        return email;
    }

    [DataMember("CustomerGroup")]
    public CustGroupId parmCustGroup(CustGroupId _custGroup = custGroup)
    {
        custGroup = _custGroup;
        return custGroup;
    }
}
```

## 2. Create the Response Contract Class

```x++
/// <summary>
/// Response contract class
/// </summary>
[DataContract]
public class ServiceResponseContract
{
    private boolean success;
    private str     message;
    private str     data;

    [DataMember("Success")]
    public boolean parmSuccess(boolean _success = success)
    {
        success = _success;
        return success;
    }

    [DataMember("Message")]
    public str parmMessage(str _message = message)
    {
        message = _message;
        return message;
    }

    [DataMember("Data")]
    public str parmData(str _data = data)
    {
        data = _data;
        return data;
    }
}
```

## 3. Create the Service Class

```x++
/// <summary>
/// Custom REST service class for customer operations
/// </summary>
public class CustomerRestService
{
    /// <summary>
    /// Get customer information by customer account
    /// </summary>
    [AifCollectionType('return', Types::Class, classStr(CustomerServiceDataContract))]
    public CustomerServiceDataContract getCustomer(CustAccount _custAccount)
    {
        CustomerServiceDataContract contract = new CustomerServiceDataContract();
        CustTable                   custTable;

        if (_custAccount)
        {
            custTable = CustTable::find(_custAccount);

            if (custTable)
            {
                contract.parmCustAccount(custTable.AccountNum);
                contract.parmCustomerName(custTable.name());
                contract.parmPhone(custTable.phone());
                contract.parmEmail(custTable.email());
                contract.parmCustGroup(custTable.CustGroup);
            }
        }

        return contract;
    }

    /// <summary>
    /// Get all customers
    /// </summary>
    [AifCollectionType('return', Types::Class, classStr(CustomerServiceDataContract))]
    public List getAllCustomers()
    {
        List                        customerList = new List(Types::Class);
        CustTable                   custTable;
        CustomerServiceDataContract contract;

        while select custTable
            where custTable.Blocked == CustVendorBlocked::No
        {
            contract = new CustomerServiceDataContract();
            contract.parmCustAccount(custTable.AccountNum);
            contract.parmCustomerName(custTable.name());
            contract.parmPhone(custTable.phone());
            contract.parmEmail(custTable.email());
            contract.parmCustGroup(custTable.CustGroup);

            customerList.addEnd(contract);
        }

        return customerList;
    }

    /// <summary>
    /// Create a new customer
    /// </summary>
    public ServiceResponseContract createCustomer(CustomerServiceDataContract _contract)
    {
        ServiceResponseContract response = new ServiceResponseContract();
        CustTable              custTable;

        try
        {
            ttsbegin;

            custTable.initValue();
            custTable.AccountNum = NumberSeq::newGetNum(CustParameters::numRefCustAccount()).num();
            custTable.CustGroup = _contract.parmCustGroup();
            custTable.insert();

            // Update additional fields
            custTable.Name = _contract.parmCustomerName();
            custTable.Phone = _contract.parmPhone();
            custTable.Email = _contract.parmEmail();
            custTable.update();

            ttscommit;

            response.parmSuccess(true);
            response.parmMessage("Customer created successfully");
            response.parmData(custTable.AccountNum);
        }
        catch (Exception::Error)
        {
            response.parmSuccess(false);
            response.parmMessage("Error creating customer");
        }

        return response;
    }

    /// <summary>
    /// Update existing customer
    /// </summary>
    public ServiceResponseContract updateCustomer(CustomerServiceDataContract _contract)
    {
        ServiceResponseContract response = new ServiceResponseContract();
        CustTable              custTable;

        try
        {
            ttsbegin;

            custTable = CustTable::find(_contract.parmCustAccount(), true);

            if (custTable)
            {
                if (_contract.parmCustomerName())
                {
                    custTable.Name = _contract.parmCustomerName();
                }
                if (_contract.parmPhone())
                {
                    custTable.Phone = _contract.parmPhone();
                }
                if (_contract.parmEmail())
                {
                    custTable.Email = _contract.parmEmail();
                }
                if (_contract.parmCustGroup())
                {
                    custTable.CustGroup = _contract.parmCustGroup();
                }

                custTable.update();

                response.parmSuccess(true);
                response.parmMessage("Customer updated successfully");
            }
            else
            {
                response.parmSuccess(false);
                response.parmMessage("Customer not found");
            }

            ttscommit;
        }
        catch (Exception::Error)
        {
            response.parmSuccess(false);
            response.parmMessage("Error updating customer");
        }

        return response;
    }

    /// <summary>
    /// Delete a customer
    /// </summary>
    public ServiceResponseContract deleteCustomer(CustAccount _custAccount)
    {
        ServiceResponseContract response = new ServiceResponseContract();
        CustTable              custTable;

        try
        {
            ttsbegin;

            custTable = CustTable::find(_custAccount, true);

            if (custTable)
            {
                custTable.delete();
                response.parmSuccess(true);
                response.parmMessage("Customer deleted successfully");
            }
            else
            {
                response.parmSuccess(false);
                response.parmMessage("Customer not found");
            }

            ttscommit;
        }
        catch (Exception::Error)
        {
            response.parmSuccess(false);
            response.parmMessage("Error deleting customer");
        }

        return response;
    }
}
```

## 4. Create the Service Group

1. In AOT, right-click on **Services** and create a new service
2. Name it `CustomerRestService`
3. Set the class property to `CustomerRestService`
4. Add service operations for each method

## 5. Create Custom Service Endpoint (Controller Class for REST)

```x++
/// <summary>
/// REST API Controller for Customer Service
/// </summary>
public class CustomerServiceController extends SysOperationServiceController
{
    /// <summary>
    /// GET endpoint to retrieve customer
    /// </summary>
    [HttpGet, Route("api/customer/{custAccount}")]
    public str getCustomer(str custAccount)
    {
        CustomerRestService         service = new CustomerRestService();
        CustomerServiceDataContract contract;
        str                        jsonResponse;

        contract = service.getCustomer(custAccount);

        // Convert to JSON
        jsonResponse = FormJsonSerializer::serializeClass(contract);

        return jsonResponse;
    }

    /// <summary>
    /// GET endpoint to retrieve all customers
    /// </summary>
    [HttpGet, Route("api/customers")]
    public str getAllCustomers()
    {
        CustomerRestService service = new CustomerRestService();
        List               customerList;
        ListEnumerator     enumerator;
        container          jsonArray;
        str                jsonResponse;

        customerList = service.getAllCustomers();
        enumerator = customerList.getEnumerator();

        while (enumerator.moveNext())
        {
            CustomerServiceDataContract contract = enumerator.current();
            jsonArray += [FormJsonSerializer::serializeClass(contract)];
        }

        jsonResponse = "[" + con2Str(jsonArray, ",") + "]";

        return jsonResponse;
    }

    /// <summary>
    /// POST endpoint to create customer
    /// </summary>
    [HttpPost, Route("api/customer")]
    public str createCustomer(str _jsonData)
    {
        CustomerRestService         service = new CustomerRestService();
        CustomerServiceDataContract contract;
        ServiceResponseContract     response;
        str                        jsonResponse;

        // Deserialize JSON to contract
        contract = FormJsonSerializer::deserializeClass(classNum(CustomerServiceDataContract), _jsonData);

        response = service.createCustomer(contract);
        jsonResponse = FormJsonSerializer::serializeClass(response);

        return jsonResponse;
    }

    /// <summary>
    /// PUT endpoint to update customer
    /// </summary>
    [HttpPut, Route("api/customer")]
    public str updateCustomer(str _jsonData)
    {
        CustomerRestService         service = new CustomerRestService();
        CustomerServiceDataContract contract;
        ServiceResponseContract     response;
        str                        jsonResponse;

        contract = FormJsonSerializer::deserializeClass(classNum(CustomerServiceDataContract), _jsonData);

        response = service.updateCustomer(contract);
        jsonResponse = FormJsonSerializer::serializeClass(response);

        return jsonResponse;
    }

    /// <summary>
    /// DELETE endpoint to delete customer
    /// </summary>
    [HttpDelete, Route("api/customer/{custAccount}")]
    public str deleteCustomer(str custAccount)
    {
        CustomerRestService     service = new CustomerRestService();
        ServiceResponseContract response;
        str                    jsonResponse;

        response = service.deleteCustomer(custAccount);
        jsonResponse = FormJsonSerializer::serializeClass(response);

        return jsonResponse;
    }
}
```

## 6. Register the Service

After creating all the classes:

1. Build and synchronize your project
2. The service will be automatically registered and available through the standard D365FO REST endpoints
3. The URL pattern will be: `https://[your-d365-url]/api/services/[ServiceGroupName]/[ServiceName]/[OperationName]`

## 7. Authentication Setup

For external applications to consume this REST service, you'll need to:

1. Register an application in Azure AD
2. Configure the application with appropriate permissions
3. Use OAuth 2.0 bearer tokens for authentication

## Example Usage (from external application):

```csharp
// C# example
using (var client = new HttpClient())
{
    client.DefaultRequestHeaders.Authorization = 
        new AuthenticationHeaderValue("Bearer", accessToken);

    var response = await client.GetAsync(
        "https://your-d365-url/api/services/CustomerServices/CustomerRestService/getCustomer?custAccount=US-001");

    var content = await response.Content.ReadAsStringAsync();
}
```

This implementation provides a complete REST service with CRUD operations for customer data in Dynamics AX/D365FO. Remember to add appropriate error handling, validation, and security measures based on your specific requirements.

